  animationTrack=Array.FindIndex(ActiveClip!.Tracks,t=>t.Mesh==mesh);animationPose=ActiveTrack!.Sample((float)animationFrame.Value);transportPoint=null;activeCargo=activeLamp=activeSmoke=-1;animationEditing=true;gizmoVisible=gizmoEditing=true;gizmoMode="rotate";if(effectBar!=null)effectBar.Visibility=Visibility.Collapsed;animationPanel.Visibility=Visibility.Visible;animationPanel.Margin=new Thickness(12,0,250,12);gizmoNumbers.Margin=new Thickness(12,0,12,260);RefreshAnimationTracks();dirty=true;await RefreshGizmo();
 }
