 async Task RefreshAnimationPose(){if(renderingPreview||!animationEditing||ActiveClip==null||ActiveTrack==null||!ready)return;await view.ExecuteScriptAsync("stopAnimation();previewAnimation("+JsonSerializer.Serialize(ActiveClip)+","+animationFrame.Value.ToString(System.Globalization.CultureInfo.InvariantCulture)+","+animationTrack+","+JsonSerializer.Serialize(animationPose)+")");}
 Vector3 AnimationPivot=>ActiveTrack==null?Vector3.Zero:new(ActiveTrack.Pivot[0],ActiveTrack.Pivot[1],ActiveTrack.Pivot[2]);
 Vector3 AnimationVector(float[] v)=>new(v[0],v[1],v[2]);
