 void DrawAnimationGraph()
 {
  if(ActiveClip!=null)animationTime.Text=UiLanguage.Text("Кадр")+": "+animationFrame.Value.ToString("F1")+" / "+ActiveClip.LastFrame+"    "+(animationFrame.Value/ActiveClip.Fps).ToString("F2")+" s";animationGraph.Children.Clear();var track=ActiveTrack;if(track==null)return;var sample=track.Sampler();double w=Math.Max(1,animationGraph.ActualWidth),h=animationGraph.Height;float[] Values(AnimationPose pose)=>animationGraphChannel.SelectedIndex switch{0=>pose.Position,2=>pose.Scale,_=>pose.Rotation};float[] all=track.Keys.SelectMany(k=>Values(k.Pose)).ToArray();double lo=Math.Min(0,all.Min()),hi=Math.Max(1,all.Max());var colours=new[]{Colors.IndianRed,Colors.MediumSeaGreen,Colors.CornflowerBlue};
